import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

// The power path, in the order energy actually travels. This order is a fact
// about the movement, not a layout decision.
const POWER_PATH = [
  {
    id: 'mainspring',
    name: 'Mainspring',
    detail: 'A 380mm hardened alloy ribbon, wound to 6.5 turns.',
    figure: '72 hours of stored energy at full wind',
  },
  {
    id: 'barrel',
    name: 'Barrel and stop-work',
    detail: 'Releases the spring at a near-constant torque and refuses the last eight per cent, where the rate would drift.',
    figure: 'Torque held within 4% across the run',
  },
  {
    id: 'train',
    name: 'Gear train',
    detail: 'Four wheels step the barrel’s one slow turn up to the escape wheel’s fast one.',
    figure: 'Ratio 1 : 4,608',
  },
  {
    id: 'escapement',
    name: 'Escapement',
    detail: 'A free-sprung lever in silicon releases the train one tooth at a time. This is the ticking.',
    figure: '5 releases per second',
  },
  {
    id: 'balance',
    name: 'Balance wheel',
    detail: 'A 10.6mm glucydur wheel swinging against a flat hairspring. Its period is what the watch calls a second.',
    figure: '18,000 semi-oscillations per hour',
  },
  {
    id: 'hands',
    name: 'Motion work and hands',
    detail: 'The last reduction divides that swing back down into minutes and hours.',
    figure: 'Cumulative deviation −1 to +4 seconds per day',
  },
]

// Physical layers, front of the movement to back. Also a fact, not an order
// chosen for the page.
const LAYERS = [
  { id: 'dial-side', name: 'Dial-side plate', thickness: '0.9mm', mm: 0.9, note: 'Carries the motion work and the hand posts.' },
  { id: 'main', name: 'Main plate', thickness: '1.4mm', mm: 1.4, note: 'German silver, frosted by hand. Every pivot is located from this one surface.' },
  { id: 'bridge', name: 'Train bridge', thickness: '0.8mm', mm: 0.8, note: 'One continuous bridge over all four train wheels, black-polished on the upper flanks.' },
  { id: 'balance-cock', name: 'Balance cock', thickness: '0.7mm', mm: 0.7, note: 'Holds the balance from one side only, so the wheel can be seen turning.' },
]

const CONFIGURATIONS = [
  {
    id: 'frosted',
    name: 'Frosted German silver',
    finish: 'Hand-frosted plates, straight-grained bridges, blued screws.',
    price: 24800,
    lead: 'Delivered from March 2027',
    remaining: 41,
  },
  {
    id: 'skeleton',
    name: 'Open-worked',
    finish: 'Main plate cut back to the load paths, every remaining edge anglaged by hand.',
    price: 39500,
    lead: 'Delivered from September 2027',
    remaining: 12,
  },
  {
    id: 'black',
    name: 'Black-polished steel',
    finish: 'Bridges polished to a true black at every angle, matte plates for contrast.',
    price: 31200,
    lead: 'Delivered from June 2027',
    remaining: 24,
  },
]

const SPECS = [
  ['Reference', 'Caliber 08'],
  ['Diameter', '31.0mm'],
  ['Height', '3.8mm'],
  ['Jewels', '27'],
  ['Frequency', '2.5 Hz (18,000 A/h)'],
  ['Power reserve', '72 hours'],
  ['Regulation', 'Free-sprung, four inertia weights'],
  ['Winding', 'Manual'],
  ['Components', '214'],
  ['Finishing hours', '62 per movement'],
]

const ATELIER = [
  'Designed, cut, and finished at the workshop in Vallée de Joux. Nothing is subcontracted except the jewels and the mainspring.',
  'Eleven watchmakers. Two of them do nothing but finishing.',
  'A total of 200 movements will be made, after which the tooling is retired.',
  'Every movement is run for 21 days in six positions before it leaves. The timing record ships with it.',
  'Serviceable indefinitely. We keep parts for retired calibers and will not stop.',
]

const RUN_TOTAL = 200
const UNALLOCATED = CONFIGURATIONS.reduce((n, c) => n + c.remaining, 0)
const chf = (n) => n.toLocaleString('en-CH')

/* ------------------------------------------------------------------ hooks */

function useReducedMotion() {
  const [reduced, setReduced] = useState(false)
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const on = () => setReduced(mq.matches)
    on()
    mq.addEventListener('change', on)
    return () => mq.removeEventListener('change', on)
  }, [])
  return reduced
}

// Regional entrance. Fires against the top of the viewport so a reveal never
// resolves behind the reader, and never re-hides once it has played.
function useReveal() {
  const ref = useRef(null)
  useEffect(() => {
    const el = ref.current
    if (!el) return
    if (!('IntersectionObserver' in window)) {
      el.classList.add('is-in')
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            e.target.classList.add('is-in')
            io.unobserve(e.target)
          }
        }
      },
      { rootMargin: '-4% 0px -18% 0px', threshold: 0 },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [])
  return ref
}

// One authored progress value for the power path, so the spine fill and the
// active station can never disagree with each other.
function usePathProgress(count) {
  const ref = useRef(null)
  const [state, setState] = useState({ p: 0, active: 0 })
  useEffect(() => {
    const el = ref.current
    if (!el) return
    let frame = 0
    const measure = () => {
      frame = 0
      const r = el.getBoundingClientRect()
      const vh = window.innerHeight
      const anchor = vh * 0.42 // read the path against the upper third
      const raw = (anchor - r.top) / Math.max(r.height - vh * 0.3, 1)
      const p = Math.min(1, Math.max(0, raw))
      const active = Math.min(count - 1, Math.max(0, Math.round(p * (count - 1))))
      setState((prev) => (prev.p === p && prev.active === active ? prev : { p, active }))
    }
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(measure)
    }
    measure()
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', onScroll)
    return () => {
      if (frame) cancelAnimationFrame(frame)
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onScroll)
    }
  }, [count])
  return [ref, state]
}

/* -------------------------------------------------------------- fragments */

function Beat({ running }) {
  return (
    <span className={running ? 'beat is-running' : 'beat'} aria-hidden="true">
      <span className="beat-dot" />
      <span className="beat-dot" />
      <span className="beat-dot" />
      <span className="beat-dot" />
      <span className="beat-dot" />
    </span>
  )
}

// 200 movements, one mark each: what is spoken for and what is still open,
// split by the finish it is open for.
function AllocationMark({ highlight }) {
  const marks = useMemo(() => {
    const out = []
    for (let i = 0; i < RUN_TOTAL - UNALLOCATED; i += 1) out.push({ k: `a${i}`, of: null })
    CONFIGURATIONS.forEach((c) => {
      for (let i = 0; i < c.remaining; i += 1) out.push({ k: `${c.id}${i}`, of: c.id })
    })
    return out
  }, [])
  return (
    <div className="alloc">
      <div
        className="alloc-grid"
        role="img"
        aria-label={`${RUN_TOTAL - UNALLOCATED} of the ${RUN_TOTAL} movements are already allocated; ${UNALLOCATED} remain unallocated.`}
      >
        {marks.map((m) => (
          <span
            key={m.k}
            className={[
              'tick',
              m.of ? 'is-open' : 'is-taken',
              highlight && m.of === highlight ? 'is-lit' : '',
              highlight && m.of && m.of !== highlight ? 'is-dim' : '',
            ].join(' ')}
          />
        ))}
      </div>
      <dl className="alloc-key">
        <div>
          <dt>{RUN_TOTAL - UNALLOCATED}</dt>
          <dd>allocated</dd>
        </div>
        <div>
          <dt>{UNALLOCATED}</dt>
          <dd>still open</dd>
        </div>
        <div>
          <dt>{RUN_TOTAL}</dt>
          <dd>and then the tooling is retired</dd>
        </div>
      </dl>
    </div>
  )
}

/* ------------------------------------------------------------------ route */

export default function App() {
  const [config, setConfig] = useState('')
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [reserved, setReserved] = useState(false)
  const [hoverConfig, setHoverConfig] = useState('')
  const [layer, setLayer] = useState('main')

  const reduced = useReducedMotion()
  const [pathRef, path] = usePathProgress(POWER_PATH.length)
  const stage = POWER_PATH[path.active]

  const beatRef = useReveal()
  const stackRef = useReveal()
  const specRef = useReveal()
  const atelierRef = useReveal()
  const chooseRef = useReveal()

  const chosen = CONFIGURATIONS.find((c) => c.id === config)
  const activeLayer = LAYERS.find((l) => l.id === layer)
  const totalMm = LAYERS.reduce((n, l) => n + l.mm, 0)

  function handleSubmit(e) {
    e.preventDefault()
    if (!name || !email || !config) return
    setReserved(true)
  }

  const onLayerKey = useCallback(
    (e) => {
      const i = LAYERS.findIndex((l) => l.id === layer)
      if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
        e.preventDefault()
        setLayer(LAYERS[Math.min(LAYERS.length - 1, i + 1)].id)
      } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
        e.preventDefault()
        setLayer(LAYERS[Math.max(0, i - 1)].id)
      }
    },
    [layer],
  )

  return (
    <div className="page">
      <a className="skip" href="#reserve">Skip to reservation</a>

      <header className="masthead">
        <span className="wordmark">Aubry &amp; Vent</span>
        <nav aria-label="Sections">
          <a href="#path">Power path</a>
          <a href="#stack">Construction</a>
          <a href="#spec">Specification</a>
          <a href="#workshop">Workshop</a>
          <a className="masthead-cta" href="#reserve">Reserve</a>
        </nav>
      </header>

      {/* 1 — orient */}
      <section className="hero" id="top">
        <div className="hero-media" aria-hidden="true" />
        <div className="hero-inner">
          <p className="eyebrow">Vallée de Joux · Manual winding · 200 pieces</p>
          <h1>
            Caliber<span className="hero-num">08</span>
          </h1>
          <p className="hero-lede">
            A manual-winding mechanical movement, made in a run of 200 and then never again.
          </p>
          <dl className="hero-rail">
            <div><dt>72 h</dt><dd>reserve</dd></div>
            <div><dt>2.5 Hz</dt><dd>beat</dd></div>
            <div><dt>31.0 mm</dt><dd>diameter</dd></div>
            <div><dt>214</dt><dd>components</dd></div>
          </dl>
          <a className="btn btn-primary hero-btn" href="#reserve">Reserve a movement</a>
        </div>
        <span className="hero-line" aria-hidden="true" />
      </section>

      {/* 2 — characterise */}
      <section className="beat-band reveal" ref={beatRef}>
        <div className="beat-band-inner">
          <p className="beat-claim">
            Seventy-two hours of stored energy, released one escape-wheel tooth at a time, five times
            a second, for three days from a single wind.
          </p>
          <div className="beat-meter">
            <Beat running={!reduced} />
            <span className="beat-label">five releases · one second</span>
          </div>
        </div>
      </section>

      {/* 3 — demonstrate (peak) */}
      <section className="path" id="path" ref={pathRef} style={{ '--p': path.p }}>
        <div className="path-head">
          <h2 className="section-title">How the energy travels</h2>
          <p className="section-note">
            One push, handed along six times. Follow it down, or jump to any stage.
          </p>
        </div>

        <div className="path-body">
          <aside className="path-aside" aria-hidden="true">
            <div className="spine">
              <span className="spine-rail" />
              <span className="spine-charge" />
              {POWER_PATH.map((s, i) => (
                <span
                  key={s.id}
                  className={['spine-node', i <= path.active ? 'is-passed' : '', i === path.active ? 'is-active' : ''].join(' ')}
                  style={{ '--i': i }}
                />
              ))}
            </div>
            <div className="path-readout">
              <p className="path-index">{String(path.active + 1).padStart(2, '0')} / 06</p>
              <p className="path-figure" key={stage.id}>{stage.figure}</p>
              {(stage.id === 'escapement' || stage.id === 'balance') && <Beat running={!reduced} />}
            </div>
          </aside>

          <ol className="path-list">
            {POWER_PATH.map((s, i) => (
              <li
                key={s.id}
                id={`stage-${s.id}`}
                data-stage={s.id}
                className={['stage', i === path.active ? 'is-active' : '', i < path.active ? 'is-passed' : ''].join(' ')}
              >
                <p className="stage-index">{String(i + 1).padStart(2, '0')}</p>
                <h3 className="stage-name">{s.name}</h3>
                <p className="stage-figure">{s.figure}</p>
                <p className="stage-detail">{s.detail}</p>
              </li>
            ))}
          </ol>
        </div>

        <nav className="path-jump" aria-label="Power path stages">
          {POWER_PATH.map((s, i) => (
            <a key={s.id} href={`#stage-${s.id}`} className={i === path.active ? 'is-active' : ''}>
              <span className="jump-i">{String(i + 1).padStart(2, '0')}</span>
              {s.name}
            </a>
          ))}
        </nav>
      </section>

      {/* 4 — transform */}
      <section className="stack reveal" id="stack" ref={stackRef}>
        <div className="stack-head">
          <h2 className="section-title">Four layers, {totalMm.toFixed(1)}mm in all</h2>
          <p className="section-note">
            The movement seen edge-on, front to back. Each layer is drawn at its real relative
            thickness; together they are the {totalMm.toFixed(1)}mm on the specification.
          </p>
        </div>

        <div className="stack-body">
          <div className="stack-figure">
            <span className="stack-bracket" aria-hidden="true"><i>{totalMm.toFixed(1)}mm</i></span>
            <div
              className="stack-bars"
              role="tablist"
              aria-orientation="vertical"
              aria-label="Layers, front to back"
              onKeyDown={onLayerKey}
            >
              {LAYERS.map((l) => (
                <button
                  key={l.id}
                  role="tab"
                  type="button"
                  id={`tab-${l.id}`}
                  aria-selected={layer === l.id}
                  aria-controls={`panel-${l.id}`}
                  tabIndex={layer === l.id ? 0 : -1}
                  data-layer={l.id}
                  className={['bar', layer === l.id ? 'is-active' : ''].join(' ')}
                  style={{ '--h': `${l.mm}` }}
                  onClick={() => setLayer(l.id)}
                  onMouseEnter={() => setLayer(l.id)}
                  onFocus={() => setLayer(l.id)}
                >
                  <span className="bar-face" />
                  <span className="bar-name">{l.name}</span>
                  <span className="bar-mm">{l.thickness}</span>
                </button>
              ))}
            </div>
          </div>

          <div
            className="stack-note"
            id={`panel-${activeLayer.id}`}
            role="tabpanel"
            aria-labelledby={`tab-${activeLayer.id}`}
          >
            <p className="stack-note-mm">{activeLayer.thickness}</p>
            <h3>{activeLayer.name}</h3>
            <p>{activeLayer.note}</p>
          </div>
        </div>
      </section>

      {/* 5 — prove, at rest */}
      <section className="spec reveal" id="spec" ref={specRef}>
        <div className="spec-head">
          <h2 className="section-title">Specification</h2>
          <p className="section-note">Measured on the running movement, not on the drawing.</p>
        </div>
        <dl className="spec-list">
          {SPECS.map(([k, v]) => (
            <div key={k} className="spec-row">
              <dt>{k}</dt>
              <dd>{v}</dd>
            </div>
          ))}
        </dl>
      </section>

      {/* 6 — prove, with the run made visible */}
      <section className="workshop reveal" id="workshop" ref={atelierRef}>
        <div className="workshop-media" aria-hidden="true" />
        <div className="workshop-inner">
          <div className="workshop-lead">
            <h2 className="section-title">The workshop</h2>
            <p className="workshop-first">{ATELIER[2]}</p>
            <AllocationMark highlight={hoverConfig || config} />
          </div>
          <ul className="workshop-facts">
            {[ATELIER[0], ATELIER[1], ATELIER[3]].map((a) => (
              <li key={a}>{a}</li>
            ))}
          </ul>
          <p className="pledge">{ATELIER[4]}</p>
        </div>
      </section>

      {/* 7 — decide */}
      <section className="choose reveal" id="reserve" ref={chooseRef}>
        <div className="choose-head">
          <h2 className="section-title">Three finishes</h2>
          <p className="section-note">Prices are for the movement alone; casing is arranged separately.</p>
        </div>

        <div className="choose-body">
          <div className="finishes" role="radiogroup" aria-label="Finish">
            {CONFIGURATIONS.map((c) => (
              <label
                key={c.id}
                data-config={c.id}
                className={['finish', config === c.id ? 'is-chosen' : ''].join(' ')}
                onMouseEnter={() => setHoverConfig(c.id)}
                onMouseLeave={() => setHoverConfig('')}
              >
                <input
                  type="radio"
                  name="finish"
                  value={c.id}
                  checked={config === c.id}
                  onChange={() => setConfig(c.id)}
                  onFocus={() => setHoverConfig(c.id)}
                  onBlur={() => setHoverConfig('')}
                />
                <span className={`finish-swatch swatch-${c.id}`} aria-hidden="true" />
                <span className="finish-body">
                  <span className="finish-name">{c.name}</span>
                  <span className="finish-desc">{c.finish}</span>
                </span>
                <span className="finish-figures">
                  <span className="finish-price">CHF {chf(c.price)}</span>
                  <span className="finish-lead">{c.lead}</span>
                  <span className="finish-left">
                    <b>{c.remaining}</b> of the run still unallocated
                  </span>
                </span>
              </label>
            ))}
          </div>

          <div className="reserve">
            {reserved ? (
              <div className="confirm" role="status">
                <p className="confirm-mark">Reserved</p>
                <p className="confirm-line">
                  {name}, we have held one <b>{chosen.name}</b> movement at{' '}
                  <b>CHF {chf(chosen.price)}</b> and will write to {email}. <b>{chosen.lead}</b>.
                </p>
                <p className="fineprint">
                  Reservations are not binding and no payment is taken now. We will write once, with
                  the timing record of the movement allocated to you.
                </p>
              </div>
            ) : (
              <form onSubmit={handleSubmit}>
                <p className="reserve-title">Reserve a movement</p>
                <div className="field">
                  <label htmlFor="config">Which finish?</label>
                  <select
                    id="config"
                    name="config"
                    required
                    value={config}
                    onChange={(e) => setConfig(e.target.value)}
                  >
                    <option value="">Choose a finish</option>
                    {CONFIGURATIONS.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.name} — CHF {chf(c.price)}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="field">
                  <label htmlFor="name">Your name</label>
                  <input
                    id="name"
                    name="name"
                    type="text"
                    required
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                  />
                </div>
                <div className="field">
                  <label htmlFor="email">Email</label>
                  <input
                    id="email"
                    name="email"
                    type="email"
                    required
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                  />
                </div>

                <p className={chosen ? 'summary is-set' : 'summary'}>
                  {chosen ? (
                    <>
                      <b>{chosen.name}</b> · CHF {chf(chosen.price)} · {chosen.lead}
                    </>
                  ) : (
                    'No finish chosen yet.'
                  )}
                </p>

                <button className="btn btn-primary" type="submit">Reserve a movement</button>
                <p className="fineprint">
                  Reservations are not binding and no payment is taken now. We will write once, with
                  the timing record of the movement allocated to you.
                </p>
              </form>
            )}
          </div>
        </div>
      </section>

      <footer className="foot">
        <div className="foot-top">
          <span className="wordmark">Aubry &amp; Vent</span>
          <p className="foot-mail">
            Enquiries: <a href="mailto:atelier@aubryvent.ch">atelier@aubryvent.ch</a>
          </p>
          <nav aria-label="Legal">
            <a href="#top">Servicing</a>
            <a href="#top">Provenance</a>
            <a href="#top">Terms of reservation</a>
          </nav>
        </div>
        <p className="foot-credit">
          Photography: macro studies of mechanical movements by{' '}
          <a href="https://www.flickr.com/photos/76491533@N00" rel="noreferrer noopener" target="_blank">
            GuySie
          </a>
          , cropped and graded, under{' '}
          <a href="https://creativecommons.org/licenses/by-sa/2.0/" rel="noreferrer noopener" target="_blank">
            CC BY-SA 2.0
          </a>
          . They are reference imagery of the horological subject, not photographs of Caliber 08.
        </p>
        <p className="foot-legal">Aubry &amp; Vent. Caliber 08. © 2026.</p>
      </footer>
    </div>
  )
}

/* ==========================================================================
   Caliber 08 — Aubry & Vent

   Colour is sampled from the movement photography used on the page: German
   silver and frosted plate (paper), gilt train wheels (brass), the ruby of a
   jewelled bearing (ruby), and the graphite of an unlit bridge.

   The page is organised around one continuous hairline — the line the energy
   travels. It starts under the hero, becomes the spine of the power path,
   becomes the edge of the layer stack, rules the specification ledger, and
   ends at the reservation.
   ========================================================================== */

:root {
  --paper: #f2eee5;
  --paper-2: #e7e1d4;
  --paper-3: #dcd5c5;
  --ink: #16140f;
  --ink-2: #3b372d;
  --muted: #746e5d;
  --hair: #cec7b6;
  --graphite: #100f0d;
  --graphite-2: #1b1915;
  --brass: #a07531;
  --brass-2: #c9a05a;
  --ruby: #8d2b38;
  --ruby-2: #b8505c;

  --serif: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;
  --sans: 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, monospace;

  --gutter: clamp(20px, 5vw, 72px);
  --max: 1240px;
  --ease: cubic-bezier(0.22, 0.61, 0.36, 1);
  --t: 160ms;
}

*,
*::before,
*::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1, h2, h3 { margin: 0; font-weight: 400; }
p { margin: 0; }
ul, ol, dl, dd { margin: 0; padding: 0; }
li { list-style: none; }
img { display: block; max-width: 100%; }

a { color: inherit; }

::selection { background: var(--ruby); color: var(--paper); }

/* ------------------------------------------------ interaction baseline --- */

a, button, input, select, label.finish {
  transition:
    color var(--t) var(--ease),
    background-color var(--t) var(--ease),
    border-color var(--t) var(--ease),
    box-shadow var(--t) var(--ease),
    transform var(--t) var(--ease),
    opacity var(--t) var(--ease);
}

:focus-visible {
  outline: 2px solid var(--ruby);
  outline-offset: 3px;
  border-radius: 1px;
}

.skip {
  position: fixed;
  top: -100px;
  left: 12px;
  z-index: 99;
  padding: 10px 16px;
  background: var(--ink);
  color: var(--paper);
  font: 500 13px/1 var(--mono);
  letter-spacing: 0.04em;
}
.skip:focus { top: 12px; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 15px 26px;
  border: 1px solid transparent;
  font: 500 13px/1 var(--mono);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
}
.btn-primary {
  background: var(--ruby);
  color: #fbf7ef;
  border-color: var(--ruby);
}
.btn-primary::after {
  content: '';
  width: 18px;
  height: 1px;
  background: currentColor;
  transition: width var(--t) var(--ease);
}
.btn-primary:hover { background: #7a232f; border-color: #7a232f; }
.btn-primary:hover::after { width: 30px; }
.btn-primary:active { transform: translateY(1px); }

/* Regional entrance — one grammar, everywhere. */
.reveal > * {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 520ms var(--ease), transform 520ms var(--ease);
}
.reveal.is-in > * { opacity: 1; transform: none; }
.reveal.is-in > *:nth-child(2) { transition-delay: 90ms; }
.reveal.is-in > *:nth-child(3) { transition-delay: 170ms; }

/* ------------------------------------------------------------- masthead --- */

.masthead {
  position: absolute;
  z-index: 6;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 24px;
  padding: 26px var(--gutter);
  color: #efe9dd;
  mix-blend-mode: normal;
}
.wordmark {
  font-family: var(--serif);
  font-size: 21px;
  letter-spacing: 0.02em;
}
.masthead nav {
  display: flex;
  align-items: baseline;
  gap: 28px;
  font: 400 12px/1 var(--mono);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.masthead nav a {
  text-decoration: none;
  padding-bottom: 4px;
  border-bottom: 1px solid transparent;
  opacity: 0.78;
}
.masthead nav a:hover { opacity: 1; border-bottom-color: var(--brass-2); }
.masthead-cta { color: var(--brass-2); opacity: 1 !important; }

/* ------------------------------------------------------------------ hero --- */

.hero {
  position: relative;
  min-height: min(92vh, 860px);
  display: flex;
  align-items: flex-end;
  padding: 140px var(--gutter) 84px;
  background: var(--graphite);
  color: #efe9dd;
  overflow: hidden;
}
.hero-media {
  position: absolute;
  inset: 0;
  background: url('/media/train-balance.jpg') center 42% / cover no-repeat;
  filter: saturate(0.42) contrast(1.12) brightness(0.62);
}
.hero-media::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(100deg, rgba(12, 11, 9, 0.94) 6%, rgba(12, 11, 9, 0.66) 42%, rgba(12, 11, 9, 0.2) 78%),
    linear-gradient(to top, rgba(12, 11, 9, 0.9), transparent 46%);
}
.hero-inner {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: var(--max);
  margin: 0 auto;
}
.eyebrow {
  font: 400 12px/1 var(--mono);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--brass-2);
  margin-bottom: 26px;
}
.hero h1 {
  font-family: var(--serif);
  font-size: clamp(64px, 12.5vw, 176px);
  line-height: 0.84;
  letter-spacing: -0.02em;
  display: flex;
  align-items: flex-start;
  gap: clamp(12px, 2vw, 26px);
}
.hero-num {
  font-family: var(--mono);
  font-size: 0.34em;
  letter-spacing: -0.01em;
  line-height: 1;
  padding-top: 0.16em;
  color: var(--brass-2);
}
.hero-lede {
  margin-top: 30px;
  max-width: 30ch;
  font-size: clamp(18px, 2vw, 22px);
  line-height: 1.45;
  color: #ded7c9;
}
.hero-rail {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  margin: 46px 0 38px;
  border-top: 1px solid rgba(206, 199, 182, 0.22);
}
.hero-rail > div {
  padding: 16px 34px 0 0;
  margin-right: 34px;
  border-right: 1px solid rgba(206, 199, 182, 0.16);
}
.hero-rail > div:last-child { border-right: 0; }
.hero-rail dt {
  font: 400 clamp(22px, 2.4vw, 30px) / 1 var(--mono);
  letter-spacing: -0.01em;
}
.hero-rail dd {
  margin-top: 7px;
  font: 400 11px/1 var(--mono);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #9c9483;
}
.hero-line {
  position: absolute;
  left: var(--gutter);
  bottom: 0;
  width: 1px;
  height: 58px;
  background: linear-gradient(to bottom, transparent, var(--brass));
  z-index: 3;
}

/* ------------------------------------------------------------ beat band --- */

.beat-band {
  background: var(--paper-2);
  border-bottom: 1px solid var(--hair);
  padding: clamp(48px, 7vw, 88px) var(--gutter);
}
.beat-band-inner {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: clamp(28px, 5vw, 72px);
  align-items: end;
}
.beat-claim {
  font-family: var(--serif);
  font-size: clamp(26px, 3.5vw, 44px);
  line-height: 1.22;
  letter-spacing: -0.01em;
  max-width: 22ch;
  text-wrap: balance;
}
.beat-meter {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 14px;
  padding-bottom: 6px;
}
.beat-label {
  font: 400 11px/1 var(--mono);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.beat { display: inline-flex; gap: 7px; }
.beat-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 1px solid var(--muted);
  background: transparent;
}
/* five releases, one second */
.beat.is-running .beat-dot { animation: tick 1s steps(1, end) infinite; }
.beat.is-running .beat-dot:nth-child(1) { animation-delay: 0ms; }
.beat.is-running .beat-dot:nth-child(2) { animation-delay: 200ms; }
.beat.is-running .beat-dot:nth-child(3) { animation-delay: 400ms; }
.beat.is-running .beat-dot:nth-child(4) { animation-delay: 600ms; }
.beat.is-running .beat-dot:nth-child(5) { animation-delay: 800ms; }
@keyframes tick {
  0%, 18% { background: var(--ruby); border-color: var(--ruby); }
  19%, 100% { background: transparent; border-color: var(--muted); }
}

/* ----------------------------------------------------------- section head --- */

.section-title {
  font-family: var(--serif);
  font-size: clamp(32px, 4.2vw, 56px);
  line-height: 1.04;
  letter-spacing: -0.015em;
}
.section-note {
  margin-top: 14px;
  max-width: 46ch;
  color: var(--muted);
  font-size: 15.5px;
}

/* ------------------------------------------------------------ power path --- */

.path {
  position: relative;
  padding: clamp(64px, 9vw, 132px) var(--gutter) clamp(40px, 6vw, 80px);
  background: var(--paper);
}
.path-head,
.path-body,
.path-jump { max-width: var(--max); margin: 0 auto; }

.path-head { padding-bottom: clamp(40px, 6vw, 76px); }

.path-body {
  display: grid;
  grid-template-columns: minmax(260px, 340px) minmax(0, 1fr);
  gap: clamp(32px, 6vw, 96px);
}

.path-aside {
  position: sticky;
  top: 0;
  height: 100vh;
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  align-content: center;
  align-items: center;
  gap: 26px;
}

.spine {
  position: relative;
  height: 310px;
  width: 40px;
}
.spine-rail,
.spine-charge {
  position: absolute;
  left: 7px;
  top: 0;
  width: 1px;
  height: 100%;
}
.spine-rail { background: var(--hair); }
.spine-charge {
  height: calc(var(--p, 0) * 100%);
  background: linear-gradient(to bottom, var(--brass-2), var(--brass));
  box-shadow: 0 0 10px rgba(160, 117, 49, 0.45);
  transition: height 90ms linear;
}
.spine-node {
  position: absolute;
  left: 3px;
  top: calc(var(--i) * 20%);
  width: 9px;
  height: 9px;
  margin-top: -4px;
  border-radius: 50%;
  border: 1px solid var(--hair);
  background: var(--paper);
  transition: all 220ms var(--ease);
}
.spine-node.is-passed { border-color: var(--brass); background: var(--brass); }
.spine-node.is-active {
  transform: scale(1.7);
  border-color: var(--ruby);
  background: var(--ruby);
  box-shadow: 0 0 0 5px rgba(141, 43, 56, 0.14);
}

.path-index {
  font: 400 11px/1 var(--mono);
  letter-spacing: 0.16em;
  color: var(--muted);
}
.path-figure {
  margin-top: 18px;
  font-family: var(--serif);
  font-size: clamp(26px, 2.6vw, 38px);
  line-height: 1.14;
  letter-spacing: -0.01em;
  color: var(--ink);
  animation: figure-in 380ms var(--ease);
}
.path-readout .beat { margin-top: 22px; }
@keyframes figure-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

.path-list { display: block; }
.stage {
  padding: clamp(30px, 4.4vw, 54px) 0 clamp(30px, 4.4vw, 54px) clamp(22px, 3vw, 42px);
  border-top: 1px solid var(--hair);
  border-left: 1px solid var(--hair);
  opacity: 0.42;
  transition: opacity 300ms var(--ease), border-color 300ms var(--ease);
}
.stage:last-child { border-bottom: 1px solid var(--hair); }
.stage.is-passed { opacity: 0.62; }
.stage.is-active { opacity: 1; border-left-color: var(--brass); }
.stage-index {
  font: 400 11px/1 var(--mono);
  letter-spacing: 0.18em;
  color: var(--muted);
}
.stage-name {
  margin-top: 12px;
  font-family: var(--serif);
  font-size: clamp(28px, 3.4vw, 44px);
  line-height: 1.06;
  letter-spacing: -0.015em;
}
.stage-figure {
  display: none;
  margin-top: 12px;
  font: 400 15px/1.4 var(--mono);
  color: var(--brass);
}
.stage-detail {
  margin-top: 14px;
  max-width: 48ch;
  color: var(--ink-2);
  font-size: 16.5px;
}

.path-jump {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 22px;
  margin-top: clamp(36px, 5vw, 64px);
  padding-top: 22px;
  border-top: 1px solid var(--hair);
  font: 400 12px/1.6 var(--mono);
  letter-spacing: 0.05em;
}
.path-jump a {
  display: inline-flex;
  gap: 8px;
  text-decoration: none;
  color: var(--muted);
  padding-bottom: 3px;
  border-bottom: 1px solid transparent;
}
.path-jump a:hover { color: var(--ink); border-bottom-color: var(--brass); }
.path-jump a.is-active { color: var(--ink); }
.path-jump .jump-i { color: var(--brass); }

/* ------------------------------------------------------------ the stack --- */

.stack {
  padding: clamp(72px, 9vw, 132px) var(--gutter);
  background: var(--paper-2);
  border-top: 1px solid var(--hair);
  border-bottom: 1px solid var(--hair);
}
.stack-head { max-width: var(--max); margin: 0 auto clamp(44px, 6vw, 72px); }
.stack-body {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: clamp(32px, 6vw, 88px);
  align-items: center;
}

.stack-figure { position: relative; padding-left: 62px; }
.stack-bracket {
  position: absolute;
  left: 22px;
  top: 0;
  bottom: 0;
  width: 12px;
  border: 1px solid var(--ink-2);
  border-right: 0;
}
.stack-bracket i {
  position: absolute;
  left: -14px;
  top: 50%;
  transform: translate(-100%, -50%);
  font: 400 12px/1 var(--mono);
  font-style: normal;
  letter-spacing: 0.04em;
  white-space: nowrap;
}
.stack-bars { display: flex; flex-direction: column; gap: 10px; }

.bar {
  position: relative;
  display: flex;
  align-items: center;
  gap: 16px;
  height: calc(var(--h) * 46px);
  padding: 0 18px 0 0;
  border: 0;
  background: none;
  text-align: left;
  cursor: pointer;
  font: inherit;
  color: inherit;
  transform-origin: left center;
}
.bar-face {
  position: absolute;
  inset: 0;
  border: 1px solid var(--ink-2);
  transition: transform var(--t) var(--ease), box-shadow var(--t) var(--ease);
}
/* Each face carries the finish its note describes. */
.bar[data-layer='dial-side'] .bar-face {
  background:
    repeating-linear-gradient(90deg, rgba(22, 20, 15, 0.16) 0 1px, transparent 1px 5px),
    linear-gradient(180deg, #d9d2c2, #c8c0ae);
}
.bar[data-layer='main'] .bar-face {
  background:
    radial-gradient(circle at 20% 30%, rgba(255, 255, 255, 0.5) 0 1px, transparent 1.6px),
    radial-gradient(circle at 60% 70%, rgba(22, 20, 15, 0.14) 0 1px, transparent 1.6px),
    linear-gradient(180deg, #cfc7b3, #bab19c);
  background-size: 7px 7px, 9px 9px, 100% 100%;
}
.bar[data-layer='bridge'] .bar-face {
  background:
    repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.34) 0 1px, rgba(22, 20, 15, 0.1) 1px 3px),
    linear-gradient(90deg, #3a362d, #6a6355 55%, #2b2822);
}
.bar[data-layer='balance-cock'] .bar-face {
  background: linear-gradient(102deg, #2b2822 8%, #8e8button 0, #9a927f 46%, #35312a 62%, #6e6759 88%);
  background: linear-gradient(102deg, #2b2822 8%, #9a927f 46%, #35312a 62%, #6e6759 88%);
}
.bar-name,
.bar-mm {
  position: relative;
  z-index: 2;
  padding: 3px 8px;
  background: rgba(242, 238, 229, 0.9);
}
.bar-name { margin-left: 16px; font-size: 14.5px; }
.bar-mm { font: 400 12.5px/1 var(--mono); color: var(--ink-2); margin-left: auto; }

.bar:hover .bar-face,
.bar:focus-visible .bar-face { box-shadow: 0 0 0 1px var(--brass); }
.bar.is-active { transform: translateX(16px); }
.bar.is-active .bar-face {
  box-shadow: -4px 0 0 0 var(--ruby), 0 8px 22px rgba(22, 20, 15, 0.14);
}

.stack-note {
  padding-left: clamp(20px, 3vw, 34px);
  border-left: 1px solid var(--hair);
}
.stack-note-mm {
  font: 400 clamp(30px, 4vw, 46px) / 1 var(--mono);
  letter-spacing: -0.02em;
  color: var(--brass);
}
.stack-note h3 {
  margin-top: 14px;
  font-family: var(--serif);
  font-size: clamp(22px, 2.4vw, 30px);
  line-height: 1.1;
}
.stack-note p:last-child {
  margin-top: 12px;
  color: var(--ink-2);
  font-size: 16.5px;
  max-width: 34ch;
}

/* --------------------------------------------------------- specification --- */

.spec { padding: clamp(72px, 9vw, 128px) var(--gutter); }
.spec-head { max-width: var(--max); margin: 0 auto clamp(36px, 5vw, 56px); }
.spec-list {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: clamp(32px, 7vw, 110px);
  border-top: 1px solid var(--ink);
}
.spec-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 20px;
  padding: 15px 0;
  border-bottom: 1px solid var(--hair);
}
.spec-row dt {
  font-size: 15px;
  color: var(--muted);
  white-space: nowrap;
}
.spec-row dd {
  font: 400 16px/1.3 var(--mono);
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.spec-row:hover dd { color: var(--ruby); }

/* -------------------------------------------------------------- workshop --- */

.workshop {
  position: relative;
  padding: clamp(78px, 10vw, 148px) var(--gutter);
  background: var(--graphite);
  color: #e7e0d2;
  overflow: hidden;
}
.workshop-media {
  position: absolute;
  inset: 0;
  background: url('/media/gear-train.jpg') center / cover no-repeat;
  filter: saturate(0.3) brightness(0.5) contrast(1.1);
}
.workshop-media::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to right, rgba(14, 13, 11, 0.95) 26%, rgba(14, 13, 11, 0.7));
}
.workshop-inner {
  position: relative;
  z-index: 2;
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: clamp(32px, 6vw, 84px) clamp(32px, 6vw, 90px);
}
.workshop .section-title { color: #f3ede1; }
.workshop-first {
  margin-top: 20px;
  font-family: var(--serif);
  font-size: clamp(20px, 2.1vw, 27px);
  line-height: 1.3;
  color: #d9d1c0;
  max-width: 26ch;
}
.alloc { margin-top: 34px; }
.alloc-grid {
  display: grid;
  grid-template-columns: repeat(25, 1fr);
  gap: 5px;
  max-width: 420px;
}
.tick {
  aspect-ratio: 1;
  border-radius: 50%;
  transition: background-color 220ms var(--ease), opacity 220ms var(--ease), transform 220ms var(--ease);
}
.tick.is-taken { background: rgba(231, 224, 210, 0.2); }
.tick.is-open { background: var(--brass-2); }
.tick.is-lit { background: var(--ruby-2); transform: scale(1.35); }
.tick.is-dim { opacity: 0.32; }
.alloc-key {
  display: flex;
  flex-wrap: wrap;
  gap: 26px;
  margin-top: 24px;
  max-width: 420px;
}
.alloc-key dt {
  font: 400 22px/1 var(--mono);
  color: #f3ede1;
}
.alloc-key dd {
  margin-top: 6px;
  font: 400 10.5px/1.3 var(--mono);
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: #9b9382;
  max-width: 14ch;
}

.workshop-facts {
  display: flex;
  flex-direction: column;
  gap: 22px;
  padding-top: 8px;
}
.workshop-facts li {
  padding-left: 22px;
  border-left: 1px solid rgba(200, 160, 90, 0.5);
  color: #cfc7b6;
  font-size: 16.5px;
  line-height: 1.55;
}
.pledge {
  grid-column: 1 / -1;
  margin-top: 8px;
  padding-top: 30px;
  border-top: 1px solid rgba(231, 224, 210, 0.16);
  font-family: var(--serif);
  font-size: clamp(24px, 3.2vw, 40px);
  line-height: 1.2;
  color: #f3ede1;
  max-width: 24ch;
}

/* ---------------------------------------------------- finishes & reserve --- */

.choose {
  padding: clamp(72px, 9vw, 132px) var(--gutter) clamp(60px, 8vw, 104px);
  background: var(--paper);
}
.choose-head { max-width: var(--max); margin: 0 auto clamp(38px, 5vw, 60px); }
.choose-body {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(320px, 0.85fr);
  gap: clamp(32px, 5vw, 72px);
  align-items: start;
}

.finishes { display: flex; flex-direction: column; }
.finish {
  position: relative;
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) minmax(0, 250px);
  gap: 26px;
  align-items: start;
  padding: 28px 26px 28px 0;
  border-top: 1px solid var(--hair);
  cursor: pointer;
}
.finish:last-of-type { border-bottom: 1px solid var(--hair); }
.finish input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}
.finish:hover { background: var(--paper-2); }
.finish.is-chosen { background: var(--paper-2); }
.finish.is-chosen::before {
  content: '';
  position: absolute;
