import { chromium } from 'playwright'
const url = 'http://localhost:4173/'
const b = await chromium.launch()
const msgs = []
async function cap(w, h, tag, full = true) {
  const p = await b.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 })
  p.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') msgs.push(`[${tag}] ${m.type()}: ${m.text()}`) })
  p.on('pageerror', e => msgs.push(`[${tag}] pageerror: ${e.message}`))
  p.on('requestfailed', r => msgs.push(`[${tag}] failed: ${r.url()}`))
  await p.goto(url, { waitUntil: 'networkidle' })
  // scroll through so reveals fire
  await p.evaluate(async () => {
    const step = window.innerHeight * 0.6
    for (let y = 0; y < document.body.scrollHeight; y += step) { window.scrollTo(0, y); await new Promise(r => setTimeout(r, 90)) }
    window.scrollTo(0, 0); await new Promise(r => setTimeout(r, 400))
  })
  const ow = await p.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth)
  msgs.push(`[${tag}] horizontal overflow px: ${ow}`)
  await p.screenshot({ path: `/tmp/shots/${tag}.png`, fullPage: full })
  return p
}
const d = await cap(1440, 900, 'desktop')
const m = await cap(390, 844, 'mobile')
await d.close(); await m.close()
console.log(msgs.join('\n'))
await b.close()
